\displaystyle \frac{dR(t)}{dt} = \gamma (N-S(t)-R(t))+u(t)(N-S(t)-R(t)),\\[0.3cm]
\displaystyle \frac{dY(t)}{dt} = bu^2(t),\\[0.3cm]
